/** Host-native instructions generated by `resonant-code init`. */

export type HostAdapter = 'codex' | 'claude';

export const HOST_WORKFLOW_REFERENCES = [
  'change',
  'context',
  'setup',
] as const;
export type HostWorkflowReference = typeof HOST_WORKFLOW_REFERENCES[number];

export function renderHostSkill(adapter: HostAdapter): string {
  const hostName = adapter === 'codex' ? 'Codex' : 'Claude Code';
  return `---
name: resonant-code
description: "Use the resonant-code CLI for concrete coding changes and explicit resonant-code setup, readiness, or decision-relevant repository-context calibration performed with ${hostName}. Do not use it for general repository questions or standalone code review."
---

# Resonant Code

Use this skill as a thin router. The CLI is the deterministic control plane and
never calls a model. Retain semantic task understanding and repository
inspection; do not recreate Runtime or RCCL policy in this skill.

## Route

- For implementation, bug fixes, features, refactors, migrations, tests, and
  other concrete repository changes, read \`references/change.md\` completely.
- For explicit installation, readiness, checks configuration, or Team Playbook
  setup, read \`references/setup.md\` completely.
- For explicit creation or refresh of durable decision-relevant repository
  observations, read \`references/context.md\` completely.
- Standalone code review is not a supported workflow yet. Keep review read-only
  and do not turn it into a change without explicit user authorization.

Read only the workflow reference needed for the current request.

## Collaboration boundary

Use human collaboration for semantic design and acceptance decisions, not as a
routine tool-permission layer.

Proceed without interrupting the user for repository-discoverable task fields,
optional-guidance selection, use of already-approved RCCL, implementation and
necessary adjacent changes that preserve the aligned intent, configured
non-destructive checks, and evidence-backed attestations for
attention-required guidance.

Inform the user without blocking for absent optional Team Playbook, RCCL, or
personal overlay.

Pause for user direction when materially different choices would change the
goal, public behavior, compatibility promise, architectural ownership,
irreversible migration strategy, persistent team authority, or acceptance of
an unresolved failure, policy exception, or design tradeoff. A transient
task-check plan is ordinary Host execution planning; a persistent team default
is a shared standard and requires semantic confirmation.
Never claim that an agent-generated approval came from a human.

## Shared boundaries

Keep run IDs, decision/evaluation IDs, fingerprints, artifact paths, and
temporary configuration paths inside the Host-to-CLI workflow. Do not surface
them in routine user updates. Present the semantic decision, its consequence,
the verification outcome, and any remaining tradeoff. Show protocol details
only when the user asks to inspect or debug the harness.

- Use \`--json\` for every Host invocation.
- Do not parse or merge Playbook policy outside Runtime.
- Do not infer semantic relations from token overlap.
- Do not invent changed files or check outcomes.
- Evaluate only guidance delivered by the prepared decision.
`;
}

export function renderHostWorkflowReference(
  adapter: HostAdapter,
  workflow: HostWorkflowReference,
): string {
  if (workflow === 'change') return renderChangeReference(adapter);
  if (workflow === 'context') return renderContextReference();
  return renderSetupReference();
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = adapter === 'codex'
    ? '.agents/skills/resonant-code/SKILL.md'
    : '.claude/skills/resonant-code/SKILL.md';
  return [
    markers.start,
    `For concrete coding changes or explicit resonant-code setup/context work, read and follow \`${skillPath}\`.`,
    'Use the `resonant-code` CLI as the deterministic change-harness control plane.',
    markers.end,
  ].join('\n');
}

function renderChangeReference(adapter: HostAdapter): string {
  const hostName = adapter === 'codex' ? 'Codex' : 'Claude Code';
  return `# Change workflow

Use this workflow only for a concrete coding change authorized by the user.
The human owns semantic authority over goals, constraints, and long-lived
tradeoffs. ${hostName} interprets and encodes that authority, makes explicitly
identified judgments, implements the change, and writes semantic attestations.
The CLI owns policy compilation, the worktree baseline, check execution, and
machine facts. Never present Agent judgment as a human decision or Runtime
fact.

## Align

Inspect the request and repository before prepare. Use the existing task fields
to carry the resulting semantic contract:

- \`task\`: the concrete goal;
- \`constraint\`: confirmed design decisions and invariants;
- \`avoid\`: non-goals and boundaries that must remain unchanged;
- \`target\`: intended ownership or impact roots for policy activation;
- \`uncertainty\`: only a still-unresolved human decision.

Do not manufacture a planning checkpoint for a self-contained task. When an
assumption is worth exposing but does not require a choice, state it briefly
and continue without waiting. When materially different approaches would
change public behavior, compatibility, architectural ownership, an
irreversible migration, or another long-lived tradeoff, ask one consolidated
question before prepare. Resolve repository-discoverable implementation
details yourself.

Treat the concrete user task as standing authorization for necessary local,
reversible execution within the aligned semantic contract. Inspect and edit
the implementation and its adjacent tests, types, configuration, and
documentation; run checks; create transient task inputs outside the
repository; and repair mechanical failures without requesting per-action
approval. Interrupt only for missing information that is necessary to proceed,
a material clarification or semantic decision, an exact exception or
verification relaxation, or an external/irreversible effect that exceeds the
task's authority. Do not turn those decisions into generic permission prompts.

Before prepare, write one transient provenance JSON file outside the
repository. Declare the source of each supplied semantic value:

\`\`\`json
{
  "description": "human-stated",
  "changeType": "agent-inferred",
  "targets": {
    "src/example.ts": "repository-derived"
  },
  "risk": "agent-inferred",
  "scope": "agent-inferred",
  "constraints": {
    "Preserve the public API.": "human-confirmed"
  }
}
\`\`\`

Allowed declared sources are \`human-stated\`, \`human-confirmed\`,
\`agent-inferred\`, and \`repository-derived\`. Use \`human-stated\` only for a
value the user actually supplied and \`human-confirmed\` only after an explicit
decision. A faithful but materially expanded Agent restatement is
\`agent-inferred\`. Runtime alone assigns \`deterministic\`. Omitted
declarations conservatively default to \`agent-inferred\`; do not add numeric
confidence.

## Prepare

After alignment, choose the smallest verification plan that can test the
requested behavior and likely regression boundary. If
\`.resonant-code/checks.json\` exists and is suitable, use it as the team
default. Otherwise inspect authoritative repository scripts, CI, and
documentation, write a transient check configuration outside the repository,
and pass it with \`--check-config\`. Every selected definition will run, so do
not add generic commands merely because they exist. This transient plan does
not require user approval.

Use schema version \`1.0\` and one explicit rationale per definition:

\`\`\`json
{
  "version": "1.0",
  "checks": [
    {
      "id": "test",
      "rationale": "Exercise the changed behavior and its regression boundary.",
      "command": ["corepack", "pnpm", "test"],
      "timeoutMs": 180000
    }
  ]
}
\`\`\`

Then run prepare before editing:

\`\`\`sh
resonant-code change prepare . \\
  --task "<concrete task>" \\
  --change-type <bugfix|feature|refactor|migration|maintenance|docs|test|unknown> \\
  --target <repository-path> \\
  --risk <low|medium|high> \\
  --scope <local|module|cross-module|repository> \\
  --provenance-file <temporary-task-provenance.json> \\
  --json
\`\`\`

Append \`--check-config <temporary-task-checks.json>\` when using a transient
Host task plan; otherwise the repository team default is selected when present.

Add repeatable \`--target\`, \`--tech\`, \`--constraint\`, \`--avoid\`, or
\`--uncertainty\` only when they are material. Supply \`change-type\`, \`risk\`,
and \`scope\` from your semantic understanding of the request and repository;
Runtime does not guess them from task wording or path counts. Use
\`change-type unknown\` or \`--uncertainty\` only to expose a material human
decision that still needs alignment.

\`--target\` is an intended change-scope root, not a prediction of the final
changed-file list. Supply the smallest justified repository-relative file or
directory roots; a directory includes its descendants. Do not guess exact
future files merely to make policy activate. Supply observed, decision-relevant
technology IDs in canonical lowercase form, such as \`typescript\`; Runtime
normalizes casing and may also infer a language from exact file extensions.

Handle results as follows:

- \`needs-alignment\`: ask one consolidated question for the reported semantic
  clarification or decision, update the task contract and provenance, and
  rerun prepare. Never phrase this as permission to continue.
- \`guidance-overflow\` with mandatory guidance within budget: select only
  task-relevant optional IDs, write
  \`{ "considerIds": [...], "rationale": "..." }\`, and rerun with
  \`--selection-file\`. Do not ask the user merely to rank optional advice.
- \`guidance-overflow\` with mandatory guidance over budget: pause for a scope,
  policy, or explicitly larger-budget decision.
- \`verification-required\`: the selected plan does not define every check
  required by delivered guidance. Inspect authoritative repository commands,
  add the missing definitions to the transient task configuration, and rerun
  prepare. Do not ask the user merely to approve command argv. This result
  creates no run or baseline.
- A returned \`runId\` establishes the compiled task contract and worktree
  baseline. Inspect \`activation\` to confirm expected Team Playbook
  contributors and checks were activated before editing. The run now owns the
  exact definitions, so delete transient task provenance and check
  configurations after prepare.

The workflow automatically loads existing Team Playbook, personal overlay, and
RCCL sources. Do not recalibrate RCCL for every task.

If a current reviewed RCCL observation has a material semantic relationship to
an active directive, provide a bounded relation file only after inspecting the
observation and its exact evidence:

\`\`\`json
{
  "relations": [
    {
      "directiveId": "directive-id",
      "observationId": "observation-id",
      "relation": "supports",
      "rationale": "Concrete task-specific semantic relationship.",
      "evidenceRefs": ["src/example.ts:10-24"]
    }
  ]
}
\`\`\`

Allowed relations are \`supports\`, \`conflicts\`, and \`limits\`. Runtime, not
the Host, decides whether a proposal can affect execution.

## Implement

Follow only the delivered guidance as normative task guidance. Targets focus
policy activation; they are not a file write allowlist. Modify adjacent tests,
types, documentation, and directly coupled implementation when necessary to
complete the aligned change, and report the actual changed files afterward.
Re-align with the user only when discovered work would change the agreed goal,
public behavior, compatibility promise, architectural ownership, irreversible
migration strategy, or another top-level tradeoff.

Full-access execution means low interruption, not expanded semantic authority.
Proceed through safe local investigation, edits, verification, and repair
without asking for approval. Clearly label non-material assumptions as Agent
judgment. If code or check facts conflict with the current human understanding,
show the evidence; do not silently preserve either side's claim.

If implementation reveals a durable missing repository boundary, finish the
aligned change unless that boundary makes the current work unsafe; suggest
context calibration separately.

## Complete

Open the exact \`evaluationInputPath\` returned by prepare and replace its empty
arrays with semantic attestations and user-approved exceptions only. Treat the
Runtime-returned \`attestationPlan.attentionItems\` as the evidence checklist.
Attest required, avoid, and tension items. Optional consider items may be
attested when materially useful, but leaving them unverified is informational
and does not require another completion run:

Before writing an attestation, perform a contradiction review over the complete
actual diff:

1. For each attention item, first try to falsify satisfaction using every
   changed file, including changes outside the supporting evidence you expect
   to cite.
2. If any changed behavior contradicts the item, or the available evidence
   does not establish it, repair the change or use \`violated\`, \`partial\`, or
   \`unverified\`. Never use \`satisfied\` merely because supporting evidence
   exists.
3. Make the explanation describe the concrete conclusion from that review,
   rather than restating the guidance.

\`\`\`json
{
  "attestations": [
    {
      "guidanceId": "delivered-guidance-id",
      "verdict": "satisfied",
      "explanation": "Concrete explanation tied to the actual change.",
      "evidenceRefs": [
        {
          "kind": "diff",
          "ref": "diff:src/example.ts",
          "file": "src/example.ts"
        }
      ]
    }
  ],
  "exceptions": []
}
\`\`\`

Evidence kinds are \`diff\`, \`file\`, \`check\`, and \`semantic\`. Diff/file
evidence must name a collected changed file, check evidence must name a
collected passing check, and semantic evidence needs a concrete description.
Use the exact field names in \`attestationPlan.evidenceExamples\`; in
particular, semantic evidence requires both \`ref\` and \`description\`.
Workflow-collected passing commands satisfy command requirements without a
Host-declared check outcome.
Never add \`changes\`, \`checks\`, or declared pass/fail outcomes to this file.

An exception may be marked \`approved\` only after the user reviews its exact
guidance ID and reason. Do not invent \`approvedBy\`.

\`\`\`sh
resonant-code change complete . \\
  --run <run-id> \\
  --json
\`\`\`

Report changed-file counts, check outcomes, guidance verdicts, exceptions, and
remaining review needs. Compare the actual diff with the aligned intent and
report the outcome in this order:

1. result;
2. core design choice implemented;
3. Runtime facts, including changes outside declared targets;
4. Agent semantic judgments, clearly identified as attestations;
5. any deviation, approved exception, or remaining human decision.

\`ready-for-adoption\` means the collected facts and evidence meet the harness
requirements for human review. It does not mean the Runtime or Agent accepted
the change on the human's behalf. Return control with a concise adoption
handoff; do not add a redundant yes/no approval prompt.

Fix safely repairable failures and rerun completion without asking. Pause only
when resolution changes the semantic contract or requires the user to accept
an unresolved failure, violation, exception, or design tradeoff.
Do not rerun completion solely to turn optional consider information into a
satisfied verdict.

After completion, propose at most one durable learning only when it would
change a future implementation or review decision. Prescriptive team consensus
belongs in the Playbook; an observed repository constraint belongs in RCCL;
local implementation detail is not persisted. Never update either source
without semantic confirmation from the user.
`;
}

function renderSetupReference(): string {
  return `# Setup and readiness workflow

Use this workflow only when the user explicitly asks to install, configure, or
inspect resonant-code readiness.

## Inspect

\`\`\`sh
resonant-code status . --json
resonant-code doctor . --strict --json
\`\`\`

Treat readiness levels differently:

- Required issues block trusted operation and must be resolved.
- Recommended items improve repository-specific guidance but do not block.
- Optional items such as RCCL and personal preferences are not setup
  requirements.

## Optional team verification defaults

An absent \`.resonant-code/checks.json\` is not a readiness failure. Normal
changes may use a transient \`--check-config\` selected by the Host. If the
file exists but is invalid, repair or remove it before relying on team
defaults.

Create or change persistent defaults only when the user or team explicitly
wants a shared future verification standard:

1. Inspect repository-owned scripts, CI definitions, and developer
   documentation with normal Host tools.
2. Propose the semantic verification purpose, expected future impact, and
   execution cost of each default. Do not guess from filenames or dependency
   presence alone.
3. Ask the user to confirm that shared standard. Keep exact argv and timeout
   visible as implementation details, not as the core approval question.
4. After semantic confirmation, write:

\`\`\`json
{
  "version": "1.0",
  "checks": [
    {
      "id": "typecheck",
      "rationale": "Validate workspace types and public TypeScript contracts.",
      "command": ["corepack", "pnpm", "typecheck"],
      "timeoutMs": 120000
    }
  ]
}
\`\`\`

Commands are argv arrays and never shell strings. Every definition in the
selected default or task configuration executes. Run
\`doctor --strict --json\` after writing a persistent file.

## Optional Team Playbook

Built-in guidance works without a local augment. When the user wants
repository-specific Playbook layers, run:

\`\`\`sh
resonant-code bootstrap prepare . --json
\`\`\`

Inspect the repository, choose only concretely supported layers, and create the
candidate requested by the prepare contract. Before
\`resonant-code bootstrap commit\`, show the user the proposed normative
statements, their scope, rationale, and how they would change future decisions.
Layer IDs, exact evidence paths, and the destination remain inspectable
protocol details handled by the Host. Commit only after the user confirms the
semantic team policy.

Do not calibrate RCCL as a generic setup step. Use \`context.md\` only for a
specific durable repository boundary whose omission could worsen a future
implementation or review decision.

## Generated artifacts

Do not hand-edit generated skill files or marked blocks. Refresh them with
\`resonant-code init .\`; use \`--force\` only after the user confirms that a
modified managed artifact may be replaced.
`;
}

function renderContextReference(): string {
  return `# Repository-context workflow

RCCL is optional and is not a repository summary. Use this workflow only when a
durable observation about compatibility, public API shape, architecture,
data-flow, migration, module format, testing, error handling, or review focus
could prevent a different and worse future decision.

Do not store versions, file lists, exported-symbol inventories, generic style,
or facts tools can cheaply rediscover. Prefer no observation over a weak one.

## Prepare a bounded contract

Select exact source windows with normal Host tools:

\`\`\`sh
resonant-code context prepare . \\
  --evidence <repository-file>:<start>-<end> \\
  --json
\`\`\`

The CLI returns immutable window IDs, exact snippets, a contract fingerprint,
and the proposal schema. Propose observations only against those window IDs.

\`\`\`yaml
schemaVersion: "1.0"
requestId: "<from-prepare>"
contextFingerprint: "<from-prepare>"
replace: false
observations:
  - id: "obs-public-api-boundary"
    category: "architecture"
    scope: "src/api/**"
    statement: "Public API construction is centralized in src/api/index.ts."
    affects: ["api-shape", "architecture-boundary"]
    decisionImpact: "A second entrypoint would split the supported public API."
    semanticConfidence: "high"
    evidence:
      - windowId: "window:<from-contract>"
\`\`\`

## Persist a generated candidate

Before writing, show the user each statement, decision impact, scope, and the
exact source evidence that supports it. Ask whether this is an accurate
repository fact worth influencing future decisions, not whether an internal
artifact may be written. After semantic confirmation:

\`\`\`sh
resonant-code context commit . \\
  --contract <prepare.json> \\
  --input <proposal.yaml> \\
  --json
\`\`\`

Committed observations remain generated and cannot change directive execution.

## Approve independently

Show the stored observation, decision impact, and evidence to the reviewer.
Only after explicit semantic review, read its current
\`lifecycle.contentFingerprint\` and run:

\`\`\`sh
resonant-code context approve . \\
  --id <observation-id> \\
  --fingerprint <observation-id>=<content-fingerprint> \\
  --approved-by <reviewer> \\
  --json
\`\`\`

Never approve an observation merely because its snippet still matches, and
never attribute approval to a human who did not provide it. A fingerprint
mismatch means the content changed and must be reviewed again. The Host handles
fingerprint binding; do not ask the user to transcribe or approve protocol
identifiers.

Use \`context validate\` for a read-only evidence check and
\`context refresh-stale\` to persist evidence lifecycle changes. Evidence
currency does not create semantic approval.
`;
}
